import csv

# Final comprehensive validation
with open('outputs/t11_city_indicator_matrix.csv', 'r', newline='', encoding='utf-8') as f:
    reader = csv.DictReader(f, fieldnames=['city_id', 'city_name', 'year', 'DE1001V', 'DE1002V', 'DE3001V', 'DE3017V', 'TT1003V', 'TT1006V', 'TT1007V', 'TT1010V'])
    rows = list(reader)

print(f'Total data rows: {len(rows)}')
print(f'Expected city-year combinations: 1612')

# Verify we have the right number of rows
if len(rows) == 1612:
    print('Row count matches expected!')
else:
    print(f'Row count mismatch: {len(rows)} vs 1612')

# Check a sample row
sample = rows[0]
print(f'Sample row: {sample}')
print(f'City: {sample[\"city_id\"]}, Name: {sample[\"city_name\"]}, Year: {sample[\"year\"]}')

# Check that all indicator columns exist
expected_indicators = ['DE1001V', 'DE1002V', 'DE3001V', 'DE3017V', 'TT1003V', 'TT1006V', 'TT1007V', 'TT1010V']
actual_indicators = list(sample.keys())[:3] + list(sample.keys())[4:]
print(f'Actual indicators: {actual_indicators}')
print(f'All indicators present: {set(actual_indicators) == set(expected_indicators)}')

# Verify the data integrity with raw data
with open('outputs/t02_eurostat_raw.csv', 'r', newline='', encoding='utf-8') as f:
    raw_reader = csv.DictReader(f)
    raw_rows = list(raw_reader)

raw_by_key = {}
for row in raw_rows:
    key = (row['city_id'], row['year'])
    ind = row['indicator_id']
    if key not in raw_by_key:
        raw_by_key[key] = {}
    raw_by_key[key][ind] = row['value']

# Now check output
output_by_key = {}
for row in rows:
    key = (row['city_id'], row['year'])
    for ind in expected_indicators:
        if ind in row:
            output_by_key[key][ind] = row[ind]

# Verify all raw data is present in output
missing_keys = []
for key in raw_by_key:
    if key not in output_by_key:
        missing_keys.append(key)

# Check for missing indicators within keys
missing_indicators = []
for key in output_by_key:
    for ind in expected_indicators:
        if ind not in output_by_key[key]:
            missing_indicators.append((key, ind))

print(f'Missing city-year keys: {len(missing_keys)}')
print(f'Missing indicators in keys: {len(missing_indicators)}')

if not missing_keys and not missing_indicators:
    print('SUCCESS: All data integrity checks passed!')
else:
    print('FAILURE: Data integrity issues found')
