with open('outputs/t11_city_indicator_matrix.csv', 'r', newline='', encoding='utf-8') as f:
    reader = csv.reader(f)
    rows = list(reader)

print(f'Total rows (including header): {len(rows)}')
print(f'Data rows: {len(rows) - 1}')
print(f'Header columns: {len(rows[0])}')
print(f'Header: {rows[0]}')

# Verify RFC 4180 compliance
with open('outputs/t11_city_indicator_matrix.csv', 'r', encoding='utf-8') as f:
    content = f.read()

# Check for proper quoting
import re
lines = content.split('\n')
has_issues = False
for line in lines:
    if ',' in line:
        # Check if any field with comma is not quoted
        parts = line.split(',')
        for part in parts:
            if ',' in part and not part.startswith('\"') and not part.endswith('\"'):
                print(f'Potential quoting issue: {line[:80]}')
                has_issues = True
                break
        else:
            continue
        break

if not has_issues:
    print('RFC 4180 compliance: PASSED')

# Verify data integrity
with open('outputs/t02_eurostat_raw.csv', 'r', newline='', encoding='utf-8') as f:
    reader = csv.DictReader(f)
    raw_rows = list(reader)

raw_by_key = {}
for row in raw_rows:
    key = (row['city_id'], row['year'])
    ind = row['indicator_id']
    if key not in raw_by_key:
        raw_by_key[key] = {}
    raw_by_key[key][ind] = row['value']

output_by_key = {}
for row in rows[1:]:
    key = (row[0], row[2])
    for col in ['DE1001V', 'DE1002V', 'DE3001V', 'DE3017V', 'TT1003V', 'TT1006V', 'TT1007V', 'TT1010V']:
        if col in row:
            output_by_key[key][col] = row[col]

missing_keys = set(raw_by_key.keys()) - set(output_by_key.keys())
missing_indicators = []
for key in output_by_key:
    for ind in ['DE1001V', 'DE1002V', 'DE3001V', 'DE3017V', 'TT1003V', 'TT1006V', 'TT1007V', 'TT1010V']:
        if ind not in output_by_key[key]:
            missing_indicators.append((key, ind))

print(f'Missing keys: {len(missing_keys)}')
print(f'Missing indicators: {len(missing_indicators)}')

if not missing_keys and not missing_indicators:
    print('Data integrity: PASSED')
else:
    print('Data integrity: FAILED')

print('\\nFinal validation: COMPLETE')
"
